#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-04
#
# create-pr/scripts/coderabbit-harvest.sh: status detection and the []-refusal.
#
# WHY: the harvest phase gated on "repo has a .coderabbit.yaml" and read [] as
# "reviewed, clean". orchestkit carried that file for ten days with the app never
# installed, so every harvest reported clean on a repo CodeRabbit had never seen
# (0 of 108 PRs with a coderabbitai comment vs 252 on platform, measured
# 2026-09-04). This test stubs gh on PATH and asserts that:
#   1. a reviewed PR still parses (positive control for the thread parser)
#   2. a reviewed PR with no threads prints [] and exits 0 (the only [] case)
#   3. an unreviewed PR in a repo with no CodeRabbit history exits 3 with EMPTY
#      stdout in read mode (the regression) and status=never_reviewed
#   4. an unreviewed PR in a repo with history is pending (5), not never_reviewed
#   5. draft / ignored title / ignored author / foreign base are skipped (4)
#   6. a failed search is unobservable (1), never reported as zero
#
# Exit codes: 0 = all pass, 1 = failures found

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../../.." && pwd)}"
HARVEST="$PROJECT_ROOT/src/skills/create-pr/scripts/coderabbit-harvest.sh"

PASS=0
FAIL=0
pass() { echo "  PASS $1"; PASS=$((PASS + 1)); }
fail() { echo "  FAIL $1"; FAIL=$((FAIL + 1)); }

TMPD=$(mktemp -d)
trap 'rm -rf "$TMPD"' EXIT

# ---------------------------------------------------------------------------
# Fake gh: dispatches on the subcommand shape the script uses.
#   gh repo view ...                 -> $FAKE_REPO
#   gh api graphql ...               -> contents of $FAKE_GRAPHQL
#   gh api -X GET search/issues ...  -> $FAKE_SEARCH_TOTAL, or failure when FAKE_SEARCH_FAIL=1
# ---------------------------------------------------------------------------
mkdir -p "$TMPD/bin"
cat > "$TMPD/bin/gh" <<'FAKE'
#!/usr/bin/env bash
case "$1 $2" in
  "repo view") printf '%s\n' "${FAKE_REPO:-acme/widgets}" ;;
  "api graphql") cat "$FAKE_GRAPHQL" ;;
  "api -X")
    if [[ "${FAKE_SEARCH_FAIL:-0}" == "1" ]]; then
      echo "gh: API rate limit exceeded (HTTP 403)" >&2; exit 1
    fi
    printf '%s\n' "${FAKE_SEARCH_TOTAL:-0}" ;;
  *) echo "fake gh: unexpected call: $*" >&2; exit 99 ;;
esac
FAKE
chmod +x "$TMPD/bin/gh"
export PATH="$TMPD/bin:$PATH"

# PR fixture builder: pr_json <draft> <title> <author> <base> <cr_review_count> <threads_json>
pr_json() {
  local draft="$1" title="$2" author="$3" base="$4" reviews="$5" threads="$6"
  jq -n -c --argjson draft "$draft" --arg title "$title" --arg author "$author" --arg base "$base" \
     --argjson reviews "$reviews" --argjson threads "$threads" \
     '{data:{repository:{pullRequest:{
        number: 42, isDraft: $draft, title: $title, baseRefName: $base, author: {login: $author},
        reviews: {nodes: ([range($reviews)] | map({author: {login: "coderabbitai"}}))},
        comments: {nodes: []},
        reviewThreads: {totalCount: ($threads | length), nodes: $threads}}}}}'
}

THREAD='[{"id":"PRRT_1","isResolved":false,"isOutdated":false,"path":"src/a.ts","line":7,"startLine":null,"originalLine":7,
  "comments":{"nodes":[{"databaseId":1001,"author":{"login":"coderabbitai"},
  "body":"_⚠️ Potential issue_ | _🔴 Critical_\n\n**Null deref on empty input.**\n\nDetails."}]}}]'

CONFIG="$TMPD/coderabbit.yaml"
cat > "$CONFIG" <<'YAML'
reviews:
  auto_review:
    enabled: true
    drafts: false
    base_branches:
      - "main"
      - "dev"
    ignore_title_keywords:
      - "chore(main): release"
      - "chore(deps"
    ignore_usernames:
      - "dependabot[bot]"
YAML
export CODERABBIT_CONFIG="$CONFIG"

run_status() {
  # prints "<exit> <status>"
  local out rc
  out=$(bash "$HARVEST" 42 --status 2>"$TMPD/stderr"); rc=$?
  printf '%s %s\n' "$rc" "$(printf '%s' "$out" | jq -r '.status // "NO_JSON"')"
}

echo "Test: coderabbit-harvest.sh status detection"
echo "────────────────────────────────────────────────────────────────────────────"

# 1. Positive control: a reviewed PR with one Critical thread still parses.
export FAKE_GRAPHQL="$TMPD/reviewed-thread.json"
pr_json false "feat: thing" "alice" "main" 1 "$THREAD" > "$FAKE_GRAPHQL"
out=$(bash "$HARVEST" 42 --unresolved 2>/dev/null); rc=$?
if [[ $rc -eq 0 ]] && [[ "$(printf '%s' "$out" | jq -r 'length, .[0].severity, .[0].title, .[0].commentId' | paste -sd, -)" == "1,critical,Null deref on empty input.,1001" ]]; then
  pass "reviewed PR: --unresolved parses the thread (exit 0, severity/title/commentId intact)"
else
  fail "reviewed PR: parser regressed (rc=$rc, out=$out)"
fi
[[ "$(run_status)" == "0 reviewed" ]] && pass "reviewed PR: --status reviewed, exit 0" || fail "reviewed PR: --status wrong: $(run_status)"

# 2. Reviewed, zero threads: the ONLY case that prints [].
export FAKE_GRAPHQL="$TMPD/reviewed-clean.json"
pr_json false "feat: thing" "alice" "main" 1 "[]" > "$FAKE_GRAPHQL"
out=$(bash "$HARVEST" 42 --unresolved 2>/dev/null); rc=$?
[[ $rc -eq 0 && "$out" == "[]" ]] && pass "reviewed PR, no threads: prints [] and exits 0" || fail "reviewed clean PR: rc=$rc out=$out"

# 3. THE REGRESSION: unreviewed PR, repo with no CodeRabbit history.
export FAKE_GRAPHQL="$TMPD/unreviewed.json"
pr_json false "feat: thing" "alice" "main" 0 "[]" > "$FAKE_GRAPHQL"
export FAKE_SEARCH_TOTAL=0
out=$(bash "$HARVEST" 42 --unresolved 2>"$TMPD/stderr"); rc=$?
if [[ $rc -eq 3 && -z "$out" ]] && grep -q "never reviewed" "$TMPD/stderr"; then
  pass "unreviewed PR, no repo history: read mode exits 3 with EMPTY stdout and says so on stderr"
else
  fail "unreviewed PR still reads as clean (rc=$rc, stdout='$out', stderr=$(cat "$TMPD/stderr"))"
fi
out=$(bash "$HARVEST" 42 2>/dev/null); rc=$?
[[ $rc -eq 3 && -z "$out" ]] && pass "unreviewed PR: plain read mode also refuses (exit 3, empty stdout)" || fail "plain read mode leaked output (rc=$rc out=$out)"
st=$(bash "$HARVEST" 42 --status 2>/dev/null); rc=$?
if [[ $rc -eq 3 ]] && [[ "$(printf '%s' "$st" | jq -r '.status, .evidence.repoPrsWithCodeRabbit, .evidence.configPresent' | paste -sd, -)" == "never_reviewed,0,true" ]] \
   && printf '%s' "$st" | jq -e '.next | test("apps/coderabbitai")' >/dev/null \
   && printf '%s' "$st" | jq -e '.reason | test("does not install")' >/dev/null; then
  pass "--status: never_reviewed, exit 3, names the install URL and the config-is-not-install fact"
else
  fail "--status never_reviewed shape wrong (rc=$rc): $st"
fi

# 4. Unreviewed PR in a repo WITH history: pending, not never_reviewed.
export FAKE_SEARCH_TOTAL=252
[[ "$(run_status)" == "5 pending" ]] && pass "unreviewed PR, repo has history: pending, exit 5" || fail "pending detection: $(run_status)"
out=$(bash "$HARVEST" 42 --unresolved 2>/dev/null); rc=$?
[[ $rc -eq 5 && -z "$out" ]] && pass "pending PR: read mode exits 5 with empty stdout" || fail "pending read mode: rc=$rc out=$out"

# 5. Config-explained skips (each must NOT reach the search call: FAKE_SEARCH_FAIL=1 would turn them into exit 1).
export FAKE_SEARCH_FAIL=1
export FAKE_GRAPHQL="$TMPD/draft.json";  pr_json true  "feat: thing" "alice" "main" 0 "[]" > "$FAKE_GRAPHQL"
[[ "$(run_status)" == "4 skipped" ]] && pass "draft PR: skipped, exit 4, no search call" || fail "draft: $(run_status)"
export FAKE_GRAPHQL="$TMPD/title.json";  pr_json false "chore(main): release 1.2.3" "alice" "main" 0 "[]" > "$FAKE_GRAPHQL"
[[ "$(run_status)" == "4 skipped" ]] && pass "ignored title: skipped, exit 4" || fail "ignored title: $(run_status)"
export FAKE_GRAPHQL="$TMPD/author.json"; pr_json false "chore(x): bump" "dependabot" "main" 0 "[]" > "$FAKE_GRAPHQL"
[[ "$(run_status)" == "4 skipped" ]] && pass "ignored author (login without [bot] suffix): skipped, exit 4" || fail "ignored author: $(run_status)"
export FAKE_GRAPHQL="$TMPD/base.json";   pr_json false "feat: thing" "alice" "release/9" 0 "[]" > "$FAKE_GRAPHQL"
[[ "$(run_status)" == "4 skipped" ]] && pass "base outside base_branches: skipped, exit 4" || fail "foreign base: $(run_status)"
unset FAKE_SEARCH_FAIL

# 5b. drafts: true in config flips the draft case through to the search.
sed -i.bak 's/drafts: false/drafts: true/' "$CONFIG"
export FAKE_GRAPHQL="$TMPD/draft.json"; export FAKE_SEARCH_TOTAL=0
[[ "$(run_status)" == "3 never_reviewed" ]] && pass "draft PR with drafts: true: not skipped, falls through to never_reviewed" || fail "drafts: true not honoured: $(run_status)"
mv "$CONFIG.bak" "$CONFIG"

# 6. Search failure is unobservable (exit 1), never zero.
export FAKE_GRAPHQL="$TMPD/unreviewed.json"; export FAKE_SEARCH_FAIL=1
st=$(bash "$HARVEST" 42 --status 2>/dev/null); rc=$?
if [[ $rc -eq 1 ]] && [[ "$(printf '%s' "$st" | jq -r '.status, .evidence.repoPrsWithCodeRabbit' | paste -sd, -)" == "unobservable,null" ]]; then
  pass "search failure: unobservable, exit 1, repoPrsWithCodeRabbit is null not 0"
else
  fail "search failure read as a measurement (rc=$rc): $st"
fi
unset FAKE_SEARCH_FAIL

# 7. No config file at all: never_reviewed still fires and says the file is missing.
export CODERABBIT_CONFIG="$TMPD/does-not-exist.yaml"; export FAKE_SEARCH_TOTAL=0
st=$(bash "$HARVEST" 42 --status 2>/dev/null); rc=$?
if [[ $rc -eq 3 ]] && printf '%s' "$st" | jq -e '.evidence.configPresent == false and (.reason | test("no .coderabbit.yaml"))' >/dev/null; then
  pass "no config: never_reviewed, configPresent=false, reason names the missing file"
else
  fail "no-config case (rc=$rc): $st"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ $FAIL -eq 0 ]]
